from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext

_CENT = Decimal("0.01")
_Q4 = Decimal("0.0001")
_TYPES = {"PURCHASE", "SALE", "CUSTOMER_RETURN", "PURCHASE_RETURN"}


def _big_prec(*vals):
    prec = 50
    for v in vals:
        if isinstance(v, Decimal):
            try:
                n_digits = len(v.as_tuple().digits)
            except Exception:
                n_digits = 50
            prec = max(prec, n_digits + 20)
            try:
                if not v.is_zero():
                    adj = v.adjusted()
                    if adj >= 0:
                        prec = max(prec, adj + 20)
            except Exception:
                pass
        elif isinstance(v, int):
            if v != 0:
                prec = max(prec, len(str(abs(v))) + 50)
    return prec


def _d2(value):
    with localcontext() as ctx:
        ctx.prec = _big_prec(value)
        return value.quantize(_CENT, rounding=ROUND_HALF_UP)


def _q4(value):
    with localcontext() as ctx:
        ctx.prec = _big_prec(value)
        return value.quantize(_Q4, rounding=ROUND_HALF_UP)


def _mul_int(d, n):
    with localcontext() as ctx:
        ctx.prec = _big_prec(d) + len(str(abs(n))) + 20 if n != 0 else _big_prec(d)
        return d * n


def _div50(num, den):
    with localcontext() as ctx:
        ctx.prec = 50
        return num / den


def _add(a, b):
    with localcontext() as ctx:
        ctx.prec = _big_prec(a, b)
        return a + b


def _sub(a, b):
    with localcontext() as ctx:
        ctx.prec = _big_prec(a, b)
        return a - b


def process_inventory(movements: list[dict]) -> dict:
    if not isinstance(movements, list):
        raise ValueError("movements must be a list")
    qty = 0
    value = Decimal("0.00")
    total_cogs = Decimal("0.00")
    total_pr = Decimal("0.00")
    for mv in movements:
        if not isinstance(mv, dict):
            raise ValueError("movement must be a dict")
        mtype = mv.get("type")
        if not isinstance(mtype, str) or mtype not in _TYPES:
            raise ValueError(f"invalid movement type: {mtype!r}")
        quantity = mv.get("quantity")
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError("quantity must be a positive int")
        if mtype == "PURCHASE":
            if "unit_cost" not in mv:
                raise ValueError("unit_cost required for PURCHASE")
            raw = mv["unit_cost"]
            if not isinstance(raw, str):
                raise ValueError("unit_cost must be a string")
            try:
                cost = Decimal(raw)
            except (InvalidOperation, ValueError):
                raise ValueError(f"invalid unit_cost: {raw!r}") from None
            if not cost.is_finite() or cost < 0:
                raise ValueError("unit_cost must be finite and >= 0")
            added = _d2(_mul_int(cost, quantity))
            value = _add(value, added)
            qty += quantity
        elif mtype == "SALE":
            if quantity > qty:
                raise ValueError("sale exceeds quantity on hand")
            avg = _div50(value, qty)
            cogs = _d2(_mul_int(avg, quantity))
            value = _d2(_sub(value, cogs))
            qty -= quantity
            total_cogs = _d2(_add(total_cogs, cogs))
        elif mtype == "CUSTOMER_RETURN":
            if qty == 0:
                raise ValueError("no current average cost for customer return")
            avg = _div50(value, qty)
            added = _d2(_mul_int(avg, quantity))
            value = _d2(_add(value, added))
            qty += quantity
        else:  # PURCHASE_RETURN
            if quantity > qty:
                raise ValueError("purchase return exceeds quantity on hand")
            avg = _div50(value, qty)
            removed = _d2(_mul_int(avg, quantity))
            value = _d2(_sub(value, removed))
            qty -= quantity
            total_pr = _d2(_add(total_pr, removed))
    if qty == 0:
        avg_out = Decimal("0.0000")
    else:
        avg_out = _q4(_div50(value, qty))
    return {
        "quantity_on_hand": qty,
        "inventory_value": _d2(value),
        "average_cost": avg_out,
        "total_cogs": _d2(total_cogs),
        "total_purchase_returns": _d2(total_pr),
    }
